document.addEventListener("DOMContentLoaded",function(){var tooltipTriggerList=[].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));var tooltipList=tooltipTriggerList.map(function(tooltipTriggerEl){return new bootstrap.Tooltip(tooltipTriggerEl)});var popoverTriggerList=[].slice.call(document.querySelectorAll('[data-bs-toggle="popover"]'));var popoverList=popoverTriggerList.map(function(popoverTriggerEl){return new bootstrap.Popover(popoverTriggerEl)});const animateOnScroll=function(){const elements=document.querySelectorAll(".animate-on-scroll");elements.forEach(element=>{const elementPosition=element.getBoundingClientRect().top;const windowHeight=window.innerHeight;if(elementPosition<windowHeight-100){element.classList.add("animated")}})};animateOnScroll();window.addEventListener("scroll",animateOnScroll);const contactForm=document.getElementById("contactForm");if(contactForm){contactForm.addEventListener("submit",function(e){e.preventDefault();const formSuccess=document.getElementById("formSuccess");setTimeout(function(){contactForm.reset();if(formSuccess){formSuccess.classList.remove("d-none");setTimeout(function(){formSuccess.classList.add("d-none")},5e3)}},1e3)})}document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener("click",function(e){e.preventDefault();const targetId=this.getAttribute("href");if(targetId==="#"||this.classList.contains("back-to-top")){window.scrollTo({top:0,behavior:"smooth"});return}const targetElement=document.querySelector(targetId);if(targetElement){window.scrollTo({top:targetElement.offsetTop-100,behavior:"smooth"})}})});(function initMobileNav(){const navCollapse=document.getElementById("navbarNav");const toggler=document.querySelector(".navbar-toggler");if(!navCollapse||!toggler)return;const setOpenState=function(isOpen){document.body.classList.toggle("nav-open",isOpen);toggler.setAttribute("aria-label",isOpen?"Fermer le menu":"Ouvrir le menu");toggler.setAttribute("aria-expanded",isOpen?"true":"false")};const closeNav=function(){if(!navCollapse.classList.contains("show"))return;if(window.bootstrap&&bootstrap.Collapse){bootstrap.Collapse.getOrCreateInstance(navCollapse,{toggle:false}).hide()}else{navCollapse.classList.remove("show");toggler.classList.add("collapsed");setOpenState(false)}};navCollapse.addEventListener("show.bs.collapse",function(){setOpenState(true)});navCollapse.addEventListener("hide.bs.collapse",function(){setOpenState(false)});navCollapse.querySelectorAll("a.nav-link:not(.dropdown-toggle), a.btn, a.mobile-menu-cta, a.mobile-menu-discover, .dropdown-item").forEach(function(link){link.addEventListener("click",function(){if(window.matchMedia("(max-width: 991.98px)").matches){closeNav()}})});document.addEventListener("keydown",function(e){if(e.key==="Escape")closeNav()});window.addEventListener("resize",function(){if(window.matchMedia("(min-width: 992px)").matches){closeNav();setOpenState(false)}})})()});